<body>
<div class="wrap">
  <header>
    <div>
      <h1>本地任务管理</h1>
      <div class="subtitle">网页界面与 JSON API 共用同一个 SQLite 数据库，重启后修改仍保留。</div>
    </div>
    <button id="addBtn">＋ 新建任务</button>
  </header>

  <div class="toolbar">
    <select id="statusFilter" aria-label="按状态筛选">
      <option value="">全部状态</option>
      <option value="open">open</option>
      <option value="in_progress">in_progress</option>
      <option value="done">done</option>
    </select>
    <input id="searchBox" type="text" placeholder="搜索标题或描述…" aria-label="搜索">
    <select id="sortSelect" aria-label="排序">
      <option value="created_at">创建时间 ↑</option>
      <option value="-created_at">创建时间 ↓</option>
      <option value="priority">优先级 ↑</option>
      <option value="-priority">优先级 ↓</option>
      <option value="title">标题 ↑</option>
      <option value="-title">标题 ↓</option>
      <option value="status">状态 ↑</option>
    </select>
    <div class="spacer"></div>
    <span id="countLabel" class="subtitle">加载中…</span>
    <button class="ghost" id="refreshBtn">刷新</button>
  </div>

  <div class="card">
    <table>
      <thead>
        <tr>
          <th style="width:170px">标题</th>
          <th>描述</th>
          <th>状态</th>
          <th>优先级</th>
          <th>创建时间</th>
          <th>操作</th>
        </tr>
      </thead>
      <tbody id="taskRows"></tbody>
    </table>
    <div class="pager">
      <button class="ghost" id="prevBtn">上一页</button>
      <span id="pageInfo">第 1 页</span>
      <button class="ghost" id="nextBtn">下一页</button>
      <select id="pageSize" aria-label="每页条数">
        <option value="5">5 条/页</option>
        <option value="10">10 条/页</option>
        <option value="20" selected>20 条/页</option>
        <option value="50">50 条/页</option>
      </select>
    </div>
  </div>

  <p class="subtitle" style="margin-top:12px">
    API 入口：<code>GET/POST /api/tasks</code> ·
    <code>GET/PUT/PATCH/DELETE /api/tasks/&lt;id&gt;</code> ·
    参数：<code>status</code>、<code>limit</code>、<code>offset</code>、<code>sort</code>、<code>q</code>
  </p>
</div>

<dialog id="taskDialog">
  <div class="dialog-inner">
    <h2 id="dialogTitle">新建任务</h2>
    <form id="taskForm">
      <input type="hidden" id="taskId">
      <label for="title">标题 *</label>
      <input type="text" id="title" maxlength="200" required placeholder="需要做什么？">
      <label for="description">描述</label>
      <textarea id="description" rows="4" placeholder="补充细节（可选）"></textarea>
      <div class="form-row">
        <div>
          <label for="status">状态</label>
          <select id="status">
            <option value="open">open</option>
            <option value="in_progress">in_progress</option>
            <option value="done">done</option>
          </select>
        </div>
        <div>
          <label for="priority">优先级（1 最低，5 最高）</label>
          <select id="priority">
            <option>1</option>
            <option selected>2</option>
            <option>3</option>
            <option>4</option>
            <option>5</option>
          </select>
        </div>
      </div>
      <div class="dialog-actions">
        <button type="button" class="ghost" id="cancelBtn">取消</button>
        <button type="submit" id="saveBtn">保存</button>
      </div>
    </form>
  </div>
</dialog>

<div id="toast"></div>

<script>
(() => {
  const state = { page: 1, limit: 20, total: 0, tasks: [] };
  const $ = (id) => document.getElementById(id);
  const rows = $("taskRows"), dialog = $("taskDialog"), form = $("taskForm");

  const esc = (value) => String(value ?? "")
    .replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;").replaceAll("'", "&#39;");

  function toast(message, isError = false) {
    const el = $("toast");
    el.textContent = message;
    el.className = isError ? "show error" : "show";
    setTimeout(() => { el.className = ""; }, 2400);
  }

  async function api(path, options = {}) {
    const response = await fetch(path, {
      headers: { "Content-Type": "application/json", ...(options.headers || {}) },
      ...options
    });
    if (response.status === 204) return { ok: true };
    let data = null;
    try { data = await response.json(); } catch (_) { data = {}; }
    if (!response.ok || data.ok === false) {
      throw new Error(data.error || `请求失败（HTTP ${response.status}）`);
    }
    return data;
  }

  function buildQuery() {
    const params = new URLSearchParams();
    const status = $("statusFilter").value;
    if (status) params.set("status", status);
    const q = $("searchBox").value.trim();
    if (q) params.set("q", q);
    params.set("sort", $("sortSelect").value);
    params.set("limit", String(state.limit));
    params.set("offset", String((state.page - 1) * state.limit));
    return params.toString();
  }

  function statusBadge(status) {
    const names = { open: "待处理", in_progress: "进行中", done: "已完成" };
    const cls = esc(status).replaceAll(" ", "_");
    return `<span class="badge ${cls}">${esc(names[status] || status)}</span>`;
  }

  function render() {
    if (!state.tasks.length) {
      rows.innerHTML = `<tr><td colspan="6" class="empty">没有符合条件的任务。点击右上角“新建任务”开始。</td></tr>`;
    } else {
      rows.innerHTML = state.tasks.map((t) => `
        <tr>
          <td class="title">${esc(t.title)}</td>
          <td class="desc">${esc(t.description || "—")}</td>
          <td>${statusBadge(t.status)}</td>
          <td>${esc(t.priority)}</td>
          <td><span class="time">${esc((t.created_at || "").replace("T", " ").slice(0, 19))}</span></td>
          <td class="row-actions">
            <button class="ghost" data-action="edit" data-id="${t.id}">编辑</button>
            <button class="danger" data-action="delete" data-id="${t.id}">删除</button>
          </td>
        </tr>`).join("");
    }
    $("countLabel").textContent = `共 ${state.total} 条`;
    const totalPages = Math.max(1, Math.ceil(state.total / state.limit));
    $("pageInfo").textContent = `第 ${state.page} / ${totalPages} 页`;
    $("prevBtn").disabled = state.page <= 1;
    $("nextBtn").disabled = state.page >= totalPages;
  }

  async function loadTasks() {
    try {
      const data = await api(`/api/tasks?${buildQuery()}`);
      state.tasks = data.items || [];
      state.total = data.total || 0;
      render();
    } catch (err) {
      toast(err.message, true);
    }
  }

  function openCreate() {
    form.reset();
    $("taskId").value = "";
    $("dialogTitle").textContent = "新建任务";
    dialog.showModal();
  }

  function openEdit(task) {
    $("taskId").value = task.id;
    $("title").value = task.title || "";
    $("description").value = task.description || "";
    $("status").value = task.status || "open";
    $("priority").value = String(task.priority || 2);
    $("dialogTitle").textContent = `编辑任务 #${task.id}`;
    dialog.showModal();
  }

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const id = $("taskId").value;
    const payload = {
      title: $("title").value.trim(),
      description: $("description").value,
      status: $("status").value,
      priority: Number($("priority").value)
    };
    try {
      if (id) {
        await api(`/api/tasks/${id}`, { method: "PUT", body: JSON.stringify(payload) });
        toast("任务已更新");
      } else {
        await api("/api/tasks", { method: "POST", body: JSON.stringify(payload) });
        toast("任务已创建");
      }
      dialog.close();
      await loadTasks();
    } catch (err) {
      toast(err.message, true);
    }
  });

  rows.addEventListener("click", async (event) => {
    const button = event.target.closest("button[data-action]");
    if (!button) return;
    const id = Number(button.dataset.id);
    if (button.dataset.action === "edit") {
      const task = state.tasks.find((t) => t.id === id);
      if (task) openEdit(task);
      return;
    }
    if (button.dataset.action === "delete") {
      if (!confirm(`确认删除任务 #${id}？该操作会写入 SQLite 并立即生效。`)) return;
      try {
        await api(`/api/tasks/${id}`, { method: "DELETE" });
        toast("任务已删除");
        if (state.tasks.length === 1 && state.page > 1) state.page -= 1;
        await loadTasks();
      } catch (err) {
        toast(err.message, true);
      }
    }
  });

  $("addBtn").addEventListener("click", openCreate);
  $("cancelBtn").addEventListener("click", () => dialog.close());
  $("refreshBtn").addEventListener("click", loadTasks);
  for (const el of [$("statusFilter"), $("sortSelect"), $("pageSize")]) {
    el.addEventListener("change", () => {
      if (el === $("pageSize")) {
        state.limit = Number($("pageSize").value);
        state.page = 1;
      } else {
        state.page = 1;
      }
      loadTasks();
    });
  }
  let searchTimer;
  $("searchBox").addEventListener("input", () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => { state.page = 1; loadTasks(); }, 250);
  });
  $("prevBtn").addEventListener("click", () => { if (state.page > 1) { state.page -= 1; loadTasks(); } });
  $("nextBtn").addEventListener("click", () => {
    const totalPages = Math.max(1, Math.ceil(state.total / state.limit));
    if (state.page < totalPages) { state.page += 1; loadTasks(); }
  });

  loadTasks();
})();
</script>
</body>
</html>
